/** Every stage, in the order an order moves through them. */
export const FUEL_ORDER_STAGES: CoreFuelStage[] = [
  "Requested",
  "Scheduled",
  "Dispatched",
  "Delivered",
  "Canceled",
];

/**
 * THE STAGE A DRIVER CHANGE LEAVES (2026-10-07). An order cannot be scheduled
 * without a driver, so picking one on a Requested order schedules it and
 * clearing it from a Scheduled one sends it back. Once it is on the road, done
 * or canceled, the driver no longer moves the stage.
 */
export function stageAfterDriver(
  status: FuelOrderStatus,
  hasDriver: boolean,
  /* THE STAGE BEFORE SCHEDULED, and whether the pick may schedule at all
     (Pavan, 2026-10-07). Sales Settings can put a stage in front of
     Scheduled, make Scheduled wait for an approval, or hold it for an
     accepted quote — `driverStage` in salesSettings.ts passes all three. */
  before: FuelOrderStatus = "Requested",
  maySchedule = true
): FuelOrderStatus {
  if (status === before && hasDriver && maySchedule) return "Scheduled";
  if (status === "Scheduled" && !hasDriver) return before;
  return status;
}

/**
 * SAMPLE STAGES — INVENTED. The source list only knew Assigned / Unassigned.
 * No driver = Requested. With a driver: past days are Delivered (a few
 * Canceled), today spreads over Scheduled, Dispatched and Delivered, and
 * later days are Scheduled.
 */
function seedStage(i: number, dayOffset: number, hasDriver: boolean): FuelOrderStatus {
  if (!hasDriver) return i % 11 === 5 ? "Canceled" : "Requested";
  if (dayOffset < 0) return i % 7 === 3 ? "Canceled" : "Delivered";
  if (dayOffset > 0) return "Scheduled";
  return (["Scheduled", "Dispatched", "Delivered"] as const)[i % 3];
}

/**
 * SAMPLE URGENCY — INVENTED (2026-10-07). The source list never showed the
 * flag, so every seventh order carries it: two of today's land early-morning
 * and still undispatched, so the overdue banner has something to count.
 */
const seedUrgent = (i: number) => i % 7 === 0;

/**
 * SAMPLE TIME IN STAGE — INVENTED (Pavan, 2026-10-07). How many hours ago
 * each order entered its stage, so the SLA flag has something to find: a few
 * Requested past a day, one Scheduled past two, some Dispatched past eight.
 */
function seedStageSince(i: number, stage: FuelOrderStatus): string {
  const hours =
    stage === "Requested"
      ? [2, 6, 30, 10, 14][i % 5]
      : stage === "Scheduled"
        ? [5, 20, 52, 12, 30, 8][i % 6]
        : stage === "Dispatched"
          ? [1, 3, 10, 4][i % 4]
          : 24;
  return new Date(Date.now() - hours * 3_600_000).toISOString();
}

/** The source list's total. Order numbers count down from the newest, as there. */
const TOTAL = 115;
const NEWEST_ORDER_NO = 4592866;

export const FUEL_ORDERS: FuelOrder[] = (() => {
  const today = startOfDay(new Date());
  return Array.from({ length: TOTAL }, (_, i) => {
    const { dayOffset, plannedTime, ...seed } = SEED[i % SEED.length];
    const when = addDays(today, dayOffset);
    return {
      ...seed,
      id: `fo-${i + 1}`,
      orderNo: String(NEWEST_ORDER_NO - i * 2),
      qtyGal: totalGal(seed.products),
      date: {
        title: DATE_FMT.format(when),
        description: relativeLabel(dayOffset, when),
      },
      dateKey: dateKeyOf(when),
      planned: plannedTime
        ? { date: DATE_FMT.format(when), time: plannedTime }
        : null,
      status: seedStage(i, dayOffset, Boolean(seed.driver)),
      stageSince: seedStageSince(i, seedStage(i, dayOffset, Boolean(seed.driver))),
      urgent: seedUrgent(i),
    };
  });
})();

/**
 * WHEN THE ORDER IS PLANNED, AS A MOMENT (2026-10-07). The row keeps it as two
 * printed strings; the overdue banner, the planned sort and the board's time
 * sorts all need one instant to compare. `null` when there is no plan or the
 * typed time does not read as one.
 */
export function plannedAt(row: FuelOrder): Date | null {
  if (!row.planned) return null;
  const day = new Date(row.planned.date);
  const t = /^(\d{1,2}):(\d{2})\s*(AM|PM)$/i.exec(row.planned.time.trim());
  if (Number.isNaN(day.getTime()) || !t) return null;
  const hour = (Number(t[1]) % 12) + (t[3].toUpperCase() === "PM" ? 12 : 0);
  return new Date(day.getFullYear(), day.getMonth(), day.getDate(), hour, Number(t[2]));
}

/**
 * Split an order's total gallons across N products.
 *
 * A bulk product change REPLACES an order's lines, and Qty (Gal) is the sum of
 * those lines — so the split has to preserve the order's own total exactly or
 * the bulk edit silently invents or destroys volume. Divides evenly and puts the
 * remainder on the FIRST line, so `sum(splitGallons(t, n)) === t` for every t
 * and n.
 *
 * ASSUMPTION, and the reason it is visible in the preview: an even split is a
 * guess. The source app has no bulk multi-product edit to copy, and nothing on
 * the order says how volume should divide between products. The confirm step
 * prints the resulting gallons per line so the operator sees the guess before
 * committing it rather than discovering it afterwards.
 */
export function splitGallons(total: number, n: number): number[] {
  if (n <= 0) return [];
  const base = Math.floor(total / n);
  const out = Array.from({ length: n }, () => base);
  out[0] += total - base * n;
  return out;
}

/** Free-text match across a row's text columns. */
export function matchesFuelOrder(row: FuelOrder, q: string): boolean {
  return [
    row.orderNo,
    row.type.label,
    row.customer.title,
    row.customer.description,
    row.products.map((p) => p.name).join(" "),
    row.date.title,
    row.planned ? `${row.planned.date} ${row.planned.time}` : "",
    row.tags.join(" "),
    row.status,
    row.driver?.name ?? "Unassigned",
  ]
    .join(" ")
    .toLowerCase()
    .includes(q);
}

import type { StatusTone } from "@/components/ui/status-chip";

/**
 * WHAT KIND OF STATE A STATUS IS — the one colour rule for every status badge in
 * Unified View, in every module: sales, 3PL, service, and whatever comes next
 * (Pavan, 2026-09-23). The rule is `docs/ds/ui/2-rules.md` §10b; the binding of
 * each module's statuses is `docs/unified-view/1-components.md` §Status kinds.
 *
 * FIVE KINDS, AND THEY ARE ABOUT WHAT THE READER SHOULD DO, not about where the
 * status sits in its lifecycle:
 *
 *   caution   WAITING ON SOMEBODY — pending, awaiting, not yet looked at
 *   info      SIMPLY TRUE — somebody is on it, it is under way. Asks nothing
 *   success   DONE — the thing it was for has happened
 *   critical  A WARNING, or a state important enough to change a plan
 *   neutral   NEITHER — a record that exists and is not yet a state; an end
 *             that is not an outcome (Canceled, Ended)
 *
 * A MODULE DECLARES KINDS, NEVER TONES. `StatusChip`'s tones are the DS's
 * channels and their names are hues-in-disguise (`processing` is amber); a map
 * written in them is a map written in colours, which is how "Assigned" came to
 * be green in sales and amber in 3PL. `npm run eval` fails a status map or a
 * chip that names a tone directly.
 */
export type StatusKind = "caution" | "info" | "success" | "critical" | "neutral";

/** Kind → the DS channel that draws it. The only place the two meet. */
export const KIND_TONE: Record<StatusKind, StatusTone> = {
  caution: "processing",
  info: "info",
  success: "success",
  critical: "failed",
  neutral: "neutral",
};

export function kindTone(kind: StatusKind): StatusTone {
  return KIND_TONE[kind];
}

/**
 * A module's status → kind map, handed back as tones so call sites keep
 * passing `tone={X_TONE[status]}`. The declaration is in kinds; the type
 * checker holds every status to one of the five.
 */
export function statusTones<S extends string>(
  kinds: Record<S, StatusKind>,
): Record<S, StatusTone> {
  const out = {} as Record<S, StatusTone>;
  for (const k in kinds) out[k] = KIND_TONE[kinds[k]];
  return out;
}

/** Active / inactive, for any record that is simply on or off — a customer, a
 *  vendor, a technician, a directory row. Being active asks nothing, so it is
 *  `info`, not `success`: nothing has been achieved by a customer existing. */
export const ACTIVE_KIND = (active: boolean): StatusKind =>
  active ? "info" : "neutral";

/*
  Shared vocabulary for the four Directory record types.

  WHY A FOURTH FILE. Customers, vendors, products and assets are different
  records, but they are the same KIND of record: each one is owned by somebody,
  carries files, accrues an edit history, and is either live or archived. Those
  four facts have identical shape everywhere, so they are declared once here.
  What is genuinely per-entity — a credit limit, a rate card, a fill threshold —
  stays in the entity's own file.

  DETERMINISM IS THE POINT. Every generator below is seeded, so the list reads
  the same on every reload and a screenshot taken today still matches the build
  tomorrow. A directory that reshuffles itself is impossible to review.

  REALISTIC MEANS INCOMPLETE. Real operational directories are not uniformly
  filled — a record entered in a hurry has no zip and no secondary phone, and
  the screen has to survive that. The `maybe` helper below is how the seed
  produces holes on purpose rather than by accident, and `NA` / `DASH` are what
  the tables print where a hole shows through.
*/

import { MONEY } from "../data";

/* ─────────────────────────────────────────────────────── missing values ── */

/**
 * Two different absences, and they are NOT the same thing.
 *
 * `N/A` means the field does not apply to this record — a nozzle has no
 * capacity, an unapproved account has no limit. `-` means it applies and
 * nobody has filled it in. Collapsing them into one glyph loses the only
 * question worth asking of a blank cell: is somebody supposed to do something
 * about it?
 */
export const NA = "N/A";
export const DASH = "–";

/** A value the record does not have. Prints `-` and sorts last. */
export const blank = (v: string | null | undefined): string =>
  v === null || v === undefined || v === "" ? DASH : v;

/** A value the record cannot have. Prints `N/A`. */
export const notApplicable = (v: string | null | undefined): string =>
  v === null || v === undefined || v === "" ? NA : v;

/* ──────────────────────────────────────────────────────────────── random ── */

/**
 * Mulberry32. Small, fast, and — the only property that matters here —
 * reproducible from its seed across every machine that runs the prototype.
 */
export function rng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export const pickFrom = <T,>(r: () => number, xs: readonly T[]): T =>
  xs[Math.floor(r() * xs.length)] as T;

export const intBetween = (r: () => number, lo: number, hi: number): number =>
  lo + Math.floor(r() * (hi - lo + 1));

/** Some of a list, never none, never all — service states, tags, capabilities. */
export function someOf<T>(r: () => number, xs: readonly T[], max = 3): T[] {
  const n = intBetween(r, 1, Math.min(max, xs.length));
  const pool = [...xs];
  const out: T[] = [];
  for (let i = 0; i < n; i += 1) {
    out.push(pool.splice(Math.floor(r() * pool.length), 1)[0] as T);
  }
  return out;
}

/**
 * A field that is present `p` of the time and null the rest.
 *
 * Used everywhere a real directory has holes. The probabilities below are not
 * uniform on purpose: a phone number is nearly always there, a tax ID often is
 * not, and a set of coordinates almost never is.
 */
export const maybe = <T,>(r: () => number, p: number, v: T): T | null =>
  r() < p ? v : null;

/* ───────────────────────────────────────────────────────────────── dates ── */

/** `YYYY-MM-DD`, the only date shape any of this data is stored in. */
export const isoDate = (d: Date): string => d.toISOString().slice(0, 10);

/** Today, for a prototype whose seed data is written around a fixed present. */
export const TODAY = new Date("2026-09-07T00:00:00Z");

export function shiftDays(from: Date, days: number): Date {
  const d = new Date(from);
  d.setUTCDate(d.getUTCDate() + days);
  return d;
}

export const dateOffset = (days: number): string => isoDate(shiftDays(TODAY, days));

const DATE_FMT = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric",
  timeZone: "UTC",
});

/** `Sep 7, 2026`, or `-` for a date the record does not carry. */
export const formatDate = (iso: string | null | undefined): string =>
  iso ? DATE_FMT.format(new Date(`${iso}T00:00:00Z`)) : DASH;

const STAMP_FMT = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric",
  hour: "numeric",
  minute: "2-digit",
  timeZone: "UTC",
});

/** `Sep 7, 2026, 9:14 AM` — the audit trail's own format. */
export const formatStamp = (iso: string): string => STAMP_FMT.format(new Date(iso));

/** Days from today, negative for the past. Drives "expires in 12 days". */
export function daysFromToday(iso: string | null): number | null {
  if (!iso) return null;
  const ms = new Date(`${iso}T00:00:00Z`).getTime() - TODAY.getTime();
  return Math.round(ms / 86_400_000);
}

/* ────────────────────────────────────────────────────────────── currency ── */

/** Money in a table cell: `-` when absent, never `$0` standing in for unknown. */
export const money = (n: number | null | undefined): string =>
  n === null || n === undefined ? DASH : MONEY(n);

/* ───────────────────────────────────────────────────────── shared shapes ── */

/**
 * One entry in a record's edit history.
 *
 * Same shape as an order's `AuditEntry` and for the same reason: an audit line
 * that says only "updated" is a line nobody can act on, so `changes` carries
 * the fields with their old value beside the new one.
 */
export interface AuditEvent {
  id: string;
  /** Full ISO stamp — the moment the save landed, not when typing began. */
  at: string;
  /** Who saved it. A person, or the name of the integration that did. */
  by: string;
  /** `Created`, `Updated`, `Archived`, `Status changed`, `Document uploaded`. */
  action: string;
  /** Field-level detail. Empty for actions with nothing to diff. */
  changes: string[];
}

export interface Attachment {
  id: string;
  name: string;
  /** `pdf`, `png`, `xlsx`, `csv` — drives the icon, nothing else. */
  kind: string;
  sizeKb: number;
  uploadedAt: string;
  uploadedBy: string;
  /** Certificates expire; a spec sheet does not. Null where the idea is moot. */
  expiresOn: string | null;
}

