export function oneLineAddress(a: {
  addressLine1: string | null;
  city: string | null;
  state: string | null;
  zip: string | null;
}): string {
  const head = [a.addressLine1, a.city].filter(Boolean).join(", ");
  const tail = [a.state, a.zip].filter(Boolean).join(" ");
